def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()
        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in ("gmail.com", "googlemail.com"):
                local = local.split("+", 1)[0].replace(".", "")
                value = f"{local}@gmail.com"
        return value

    def valid_email(value):
        if value.count("@") != 1:
            return False
        local, domain = value.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) == 10 and digits[0] not in "01":
            return digits
        return ""

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        email = email if valid_email(email) else ""
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        prepared.append({
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
            "opted_out": row["opted_out"].strip().lower() in {"y", "yes", "true", "1"},
            "updated_dt": parse_updated(row["updated"]),
        })

    # Build connected components, since matches are transitive.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}
    for i, person in enumerate(prepared):
        if person["email"]:
            if person["email"] in email_owner:
                union(i, email_owner[person["email"]])
            else:
                email_owner[person["email"]] = i

        if person["phone"] and person["last_name"]:
            key = (person["phone"], person["last_name"].casefold())
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def preferred(rows, field):
        candidates = [person for person in rows if person[field]]
        if not candidates:
            return ""
        winner = min(
            candidates,
            key=lambda person: (
                person["source"] != "manual",
                -person["updated_dt"].timestamp(),
                person["index"],
            ),
        )
        return winner[field]

    output = []
    for group in sorted(groups.values(), key=lambda group: min(p["index"] for p in group)):
        latest = max(person["updated_dt"] for person in group)
        output.append({
            "first_name": preferred(group, "first_name"),
            "last_name": preferred(group, "last_name"),
            "zip": preferred(group, "zip"),
            "email": preferred(group, "email"),
            "phone": preferred(group, "phone"),
            "source": preferred(group, "source"),
            "tags": ";".join(sorted(set().union(*(person["tags"] for person in group)))),
            "opted_out": "Y" if any(person["opted_out"] for person in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
